import 'package:flutter/material.dart';
import 'package:provider/provider.dart';
import '../../services/devhub_api.dart';
import '../../core/app_theme.dart';
import '../../widgets/devhub_widgets.dart';
class PublicProfileScreen extends StatefulWidget{final String username;const PublicProfileScreen({super.key,required this.username});@override State<PublicProfileScreen> createState()=>_PublicProfileScreenState();}
class _PublicProfileScreenState extends State<PublicProfileScreen>{late Future<Map<String,dynamic>> future;@override void initState(){super.initState();future=context.read<DevHubApi>().publicProfile(widget.username);}
 @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Developer profile')),body:FutureBuilder<Map<String,dynamic>>(future:future,builder:(context,s){if(s.connectionState==ConnectionState.waiting)return const LoadingView();if(s.hasError)return ErrorView(message:'${s.error}',retry:()=>setState(()=>future=context.read<DevHubApi>().publicProfile(widget.username)));final user=Map<String,dynamic>.from(s.data?['user']??{});final skills=List<dynamic>.from(s.data?['skills']??[]);final repos=List<dynamic>.from(s.data?['repos']??[]);return ListView(padding:const EdgeInsets.all(18),children:[Panel(child:Column(children:[InitialAvatar(name:'${user['name']??widget.username}',url:'${user['avatarUrl']??''}',size:82),const SizedBox(height:12),Text('${user['name']??widget.username}',style:Theme.of(context).textTheme.headlineMedium),Text('@${user['username']??widget.username}',style:const TextStyle(color:AppColors.muted)),const SizedBox(height:12),Text('${user['bio']??''}',textAlign:TextAlign.center,style:const TextStyle(color:AppColors.muted))])),const SizedBox(height:18),SectionTitle('Skills'),const SizedBox(height:10),Wrap(spacing:7,runSpacing:7,children:skills.map((e)=>SkillPill(e is Map?'${e['name']}':'$e')).toList()),const SizedBox(height:20),SectionTitle('Repositories'),const SizedBox(height:10),...repos.map((e){final r=Map<String,dynamic>.from(e);return Padding(padding:const EdgeInsets.only(bottom:8),child:Panel(child:Row(children:[Expanded(child:Text('${r['name']??'Repository'}',style:const TextStyle(fontWeight:FontWeight.bold))),Text('★ ${r['stars']??0}',style:const TextStyle(color:AppColors.amber))])));})]);}));}
